// 第二轮独立编写；与考试池隔离。不使用参数枚举增加题数。
const courses={network:[],structures:[],programming:[]};
function add(chapter,section,entries){addCourse('network',chapter,section,entries);}
function addCourse(subject,chapter,section,entries){const bank=courses[subject];for(const [stem,...parts]of entries){
 const q={id:`P3-${subject}-${chapter}-${bank.filter(q=>q.chapter===chapter).length+1}`,chapter,section,revision:1,pool:'practice',origin:'原创',stem};
 if(section==='选择题'||section==='判断题'){q.type='single';[q.options,q.answer,q.explanation]=parts;const shift=section==='选择题'?Array.from(q.id).reduce((v,c)=>v+c.charCodeAt(0),0)%q.options.length:0;const options=q.options;q.options=options.map((_,i)=>options[(i+shift)%options.length]);q.answer=(q.answer-shift+options.length)%options.length;}
 else if(section==='填空题'){q.type='fill';const [answers,explanation]=parts;q.answers=answers.map(v=>Array.isArray(v)?v:[String(v)]);q.formats=answers.map(v=>typeof v==='number'?'number':'text');q.explanation=explanation;}
 else{q.type='short';[q.model,q.rubric]=parts;}
 bank.push(q);
}}
