addCourse('programming',6,'程序填空',[
 ['补齐统计小于x的元素个数，n≥0。\n```c\nint less(const int a[],int n,int x){int c=0;\n for(int i=0;/*①*/;i++)if(/*②*/)c++;\n return /*③*/;}\n```','①i<n；②a[i]<x；③c。',['下标边界','比较元素与阈值','返回计数']],
 ['补齐寻找最后一个最大值位置，n>0。\n```c\nint lastMax(const int a[],int n){int k=0;\n for(int i=1;i<n;i++)if(/*①*/)k=/*②*/;\n return /*③*/;}\n```','①a[i]>=a[k]；②i；③k。相等时更新才能保留最后一次。',['相等也更新','保存下标而非值','返回合法下标']],
 ['补齐非递减判定，n≥0，空数组视为非递减。\n```c\nint ordered(const int a[],int n){\n for(int i=1;i<n;i++)if(/*①*/)return /*②*/;\n return /*③*/;}\n```','①a[i]<a[i-1]；②0；③1。',['找到逆序即失败','允许相等','空数组自然成功']],
 ['补齐删除下标k后将右侧元素左移，0≤k<n。\n```c\nfor(int i=k;i</*①*/;i++)a[i]=/*②*/;\n n=/*③*/;\n```\n这里任务是删除后保持原顺序。','①n-1；②a[i+1]；③n-1。搬动的是右侧元素向左填空。',['不读取a[n]','正确相邻来源','有效长度减一']],
 ['补齐在下标k前插入x，0≤k≤n且容量至少n+1。\n```c\nfor(int i=n;i>/*①*/;i--)a[i]=/*②*/;\n a[k]=x; n=/*③*/;\n```','①k；②a[i-1]；③n+1。',['倒序右移','包含原k项','长度增长']],
 ['补齐稳定压缩非零项。\n```c\nint k=0;\nfor(int i=0;i<n;i++)if(/*①*/)a[k++]=/*②*/;\nreturn /*③*/;\n```','①a[i]!=0；②a[i]；③k。读指针i不落后于写指针k，能原地完成。',['非零判据','保留原顺序','返回新有效长度']],
 ['补齐每列求和，矩阵n行3列，sum容量3，数值保证int不溢出。\n```c\nfor(int j=0;j<3;j++){sum[j]=/*①*/;\n for(int i=0;i<n;i++)sum[j]+=/*②*/;\n}\n```','①0；②a[i][j]。固定列j，遍历行i。',['列和先清零','行列访问次序','不累入其他列']],
 ['补齐长度n数组复制到不同的b，容量足够。\n```c\nfor(int i=/*①*/;i</*②*/;i++)b[i]=/*③*/;\n```','①0；②n；③a[i]。',['完整0至n−1','不越界','源目标正确']],
 ['补齐整数数组元素相等比较，长度相同。\n```c\nint equal(const int a[],const int b[],int n){\n for(int i=0;i<n;i++)if(/*①*/)return 0;\n return /*②*/;}\n```','①a[i]!=b[i]；②1。任何位置不同即失败，全相同才成功。',['逐项比较','早停条件','空序列也相等']],
 ['补齐计算相邻差值，n≥1，输出b有n−1项，差值保证int可表示。\n```c\nfor(int i=0;i</*①*/;i++)b[i]=/*②*/;\n```','①n-1；②a[i+1]-a[i]。',['输出长度','后一项减前一项','n=1无访问输出']],
 ['补齐每行最大值，n行3列。\n```c\nfor(int i=0;i<n;i++){int x=/*①*/;\n for(int j=1;j<3;j++)if(/*②*/)x=a[i][j];\n result[i]=/*③*/;}\n```','①a[i][0]；②a[i][j]>x；③x。',['首项为候选','每行独立','正确比较及写回']],
 ['补齐数字0至9频率表，n≥0且a中值合法。\n```c\nfor(int d=0;d<10;d++)freq[d]=/*①*/;\nfor(int i=0;i<n;i++)freq[/*②*/]++;\n```','①0；②a[i]。',['清空全部桶','按值而非下标记频率','输入值域前提']],
 ['补齐找第一个相邻相等对的左下标，无则−1。\n```c\nfor(int i=0;i+1<n;i++)if(/*①*/)return /*②*/;\nreturn /*③*/;\n```','①a[i]==a[i+1]；②i；③-1。',['两项都合法','返回左位置','无结果状态']],
 ['补齐从方阵3×3取副对角线和，数值保证int不溢出。\n```c\nint s=0;\nfor(int i=0;i<3;i++)s+=a[i][/*①*/];\nreturn /*②*/;\n```','①2-i；②s。副对角线坐标和为2。',['不是主对角i','三项坐标正确','返回总和']],
 ['补齐寻找最小正整数元素，若无正数返回0；输出值作为不存在标记合法，因为0不是正数。\n```c\nint best=0;\nfor(int i=0;i<n;i++)if(a[i]>0 && (/*①*/))best=/*②*/;\nreturn best;\n```','①best==0||a[i]<best；②a[i]。',['不存在与正值不冲突','只纳入正数','候选更新']]
]);
addCourse('programming',6,'编程题',[
 ['实现int countBelow(const int a[],int n,int x)，返回严格小于x的元素数。n≥0，n>0时a有效。','int countBelow(const int a[],int n,int x){int c=0;for(int i=0;i<n;i++)if(a[i]<x)c++;return c;}\n每项独立与x比较，不能把下标或前缀和当比较对象。',['遍历边界','严格小于','空数组0']],
 ['实现int lastMin(const int a[],int n)，返回最后一个最小值下标，n=0返回−1。','int lastMin(const int a[],int n){if(n==0)return -1;int k=0;for(int i=1;i<n;i++)if(a[i]<=a[k])k=i;return k;}\n小于或等于都更新，才能选最后而非最先。',['空数组','保留下标','相等时更新']],
 ['实现int compactPositive(int a[],int n)，原地保留所有正数并保持次序，返回新长度；不要求清除新长度之后旧值。','int compactPositive(int a[],int n){int k=0;for(int i=0;i<n;i++)if(a[i]>0)a[k++]=a[i];return k;}\n写入位置始终不超过读取位置，不会覆盖尚未读的数据。',['正值判据','稳定与读写指针','正确新长度']],
 ['实现void prefix(const int a[],int n,long long s[])，s容量n+1，s[0]=0，s[i+1]为a前i+1项和。保证所有累计值可用long long表示。','void prefix(const int a[],int n,long long s[]){s[0]=0;for(int i=0;i<n;i++)s[i+1]=s[i]+a[i];}\n先定义空前缀，随后每步只新增当前一项。',['n+1个输出','空前缀0','递推关系']],
 ['实现long long rangeSum(const long long s[],int l,int r)，已知s为上一题定义的前缀和，求闭区间[l,r]和，0≤l≤r。','long long rangeSum(const long long s[],int l,int r){return s[r+1]-s[l];}\n前r+1项去掉前l项，正好留下l至r，不应写s[r]-s[l]。',['闭区间端点','正确前缀下标','无需重复遍历']],
 ['实现void differences(const int a[],int n,long long b[])，把相邻后一项减前一项写入b，n≥1、b容量n−1。减法需避免先在int中溢出。','void differences(const int a[],int n,long long b[]){for(int i=0;i+1<n;i++)b[i]=(long long)a[i+1]-a[i];}\n先转long long再减，不能减完才转。',['n−1项','差值方向','先提升再运算']],
 ['实现int shiftLeft(int a[],int n,int k)，删除数组前k项并稳定左移，返回新长度。0≤k≤n，不循环回填。','int shiftLeft(int a[],int n,int k){for(int i=k;i<n;i++)a[i-k]=a[i];return n-k;}\n这是删除前缀，不是循环左移；k=n时返回0。',['正确来源下标','保持顺序','k=0及k=n']],
 ['实现int insert(int a[],int *n,int cap,int k,int x)。0≤*n≤cap；若k不在[0,*n]或已满，返回0且不改数据；否则在k前插入并返回1。','int insert(int a[],int *n,int cap,int k,int x){if(k<0||k>*n||*n==cap)return 0;for(int i=*n;i>k;i--)a[i]=a[i-1];a[k]=x;(*n)++;return 1;}',['先验合法性和容量','从后向前移动','插首尾及空表']],
 ['实现int erase(int a[],int n,int l,int r)，删除闭区间[l,r]并稳定压缩，已知0≤l≤r<n，返回新长度。','int erase(int a[],int n,int l,int r){int k=l;for(int i=r+1;i<n;i++)a[k++]=a[i];return k;}\n前l项保留，后缀接到l开始；新长n−(r−l+1)。',['区间含两端','后缀左移','返回长度']],
 ['实现void rowSums(const int a[][4],int n,long long sums[])，输出每行4个数之和，n≥0，所有和可表示。','void rowSums(const int a[][4],int n,long long sums[]){for(int i=0;i<n;i++){long long s=0;for(int j=0;j<4;j++)s+=a[i][j];sums[i]=s;}}',['每行清零','行列界限','long long累计']],
 ['实现int largestRow(const int a[][3],int n)，返回行和最大的首个行下标，n=0返回−1，和值用long long且可表示。','int largestRow(const int a[][3],int n){if(n==0)return -1;int best=0;long long max=0;for(int j=0;j<3;j++)max+=a[0][j];for(int i=1;i<n;i++){long long s=0;for(int j=0;j<3;j++)s+=a[i][j];if(s>max){max=s;best=i;}}return best;}',['空矩阵','首行初始化而非0哨兵','只在严格更大时更新','逐行重算']],
 ['实现int nondecreasing(const int a[],int n)，判断非递减，空数组返回1。','int nondecreasing(const int a[],int n){for(int i=1;i<n;i++)if(a[i]<a[i-1])return 0;return 1;}\n只需检查是否存在相邻下降，相等是允许的。',['相邻判据','允许相等','短数组']],
 ['实现int mismatch(const int a[],const int b[],int n)，返回首个不同位置，无不同返回−1。','int mismatch(const int a[],const int b[],int n){for(int i=0;i<n;i++)if(a[i]!=b[i])return i;return -1;}\n比较的是序列位置，不是忽略顺序的元素集合。',['首个差异早停','两数组同界限','n=0返回−1']],
 ['实现void bubblePass(int a[],int n)，只从左到右做一趟升序冒泡，相邻逆序才交换。不得直接把全表排完冒充一趟。','void bubblePass(int a[],int n){for(int i=0;i+1<n;i++)if(a[i]>a[i+1]){int t=a[i];a[i]=a[i+1];a[i+1]=t;}}\n完成后最大值到末端，其他部分未必全有序。',['一趟而非全部','相邻比较交换','n<2安全']],
 ['实现int copyOdd(const int a[],int n,int b[])，复制所有奇数至b且保持顺序，b容量足够，元素允许负数，返回数量。','int copyOdd(const int a[],int n,int b[]){int k=0;for(int i=0;i<n;i++)if(a[i]%2!=0)b[k++]=a[i];return k;}\n负奇数余数不一定是1，应检查非0。',['正负奇数','稳定复制','返回数量']],
 ['实现void digitFreq(const int a[],int n,int freq[10])，输入值全部在0至9，输出频率，必须先清空输出。','void digitFreq(const int a[],int n,int freq[10]){for(int i=0;i<10;i++)freq[i]=0;for(int i=0;i<n;i++)freq[a[i]]++;}',['清零全部桶','按值索引','利用明确值域']],
 ['实现int mostFrequentDigit(const int a[],int n)，输入0至9且n>0，返回频率最高的值，平局返回较小值。','int mostFrequentDigit(const int a[],int n){int f[10]={0};for(int i=0;i<n;i++)f[a[i]]++;int best=0;for(int d=1;d<10;d++)if(f[d]>f[best])best=d;return best;}\n从小到大检查且只严格更大时更新，平局留较小值。',['频率而非最大数值','正确计数','平局规则']],
 ['数组a长n，恰包含0至n中除一个以外的所有整数且互异，n≥0。实现int missing(const int a[],int n)，O(n)时间、O(1)空间，不用可能溢出的求和。','int missing(const int a[],int n){int x=n;for(int i=0;i<n;i++)x^=i^a[i];return x;}\n每个成对出现的值异或抵消，只留下缺失值。n=0返回0。',['利用互异完整域前提','异或全部域与输入','无求和溢出']],
 ['实现int twoSum(const int a[],int n,int target,int *l,int *r)，a非递减；若有不同下标两数和为target，输出一对并返回1，无则0且不改输出。求和用long long。','int twoSum(const int a[],int n,int target,int *l,int *r){int i=0,j=n-1;while(i<j){long long s=(long long)a[i]+a[j];if(s==target){*l=i;*r=j;return 1;}if(s<target)i++;else j--;}return 0;}\n小和向右增，大和向左减；不是在无序数组上直接套双指针。',['有序前提','下标不同','和先提升','失败输出不变']],
 ['实现int longestSame(const int a[],int n)，返回最长连续相等段长度，空为0。','int longestSame(const int a[],int n){if(n==0)return 0;int cur=1,best=1;for(int i=1;i<n;i++){cur=a[i]==a[i-1]?cur+1:1;if(cur>best)best=cur;}return best;}\n连续性看相邻，而非某值全局出现频率。',['空数组','当前段与最长分离','非连续重复不合并']],
 ['实现long long minWindowSum(const int a[],int n,int k)，0<k≤n，返回连续k项和的最小值；和值可表示。要求O(n)时间。','long long minWindowSum(const int a[],int n,int k){long long cur=0;for(int i=0;i<k;i++)cur+=a[i];long long best=cur;for(int i=k;i<n;i++){cur-=a[i-k];cur+=a[i];if(cur<best)best=cur;}return best;}\n每步移出旧首、加入新尾，不重新累加整段。',['先形成首窗口','删旧加新','允许负数','线性时间']],
 ['实现void colMax(const int a[][3],int n,int out[3])，n>0，输出各列最大值。','void colMax(const int a[][3],int n,int out[3]){for(int j=0;j<3;j++){int m=a[0][j];for(int i=1;i<n;i++)if(a[i][j]>m)m=a[i][j];out[j]=m;}}\n每列从本列首项初始化，不能把0当适用于所有负数输入的最大候选。',['列独立','初值来自数据','全部为负时正确']],
 ['实现void diagonalSums(const int a[3][3],long long *main,long long *anti)，分别返回主、副对角线和。中间元素应各计入对应对角线。','void diagonalSums(const int a[3][3],long long *main,long long *anti){long long x=0,y=0;for(int i=0;i<3;i++){x+=a[i][i];y+=a[i][2-i];}*main=x;*anti=y;}\n这是两个独立和，不是在求两条对角线并集。',['两组坐标','中心各入一和','输出类型']],
 ['实现void rotate90(const int a[3][3],int b[3][3])，顺时针转90°写入不重叠的b。','void rotate90(const int a[3][3],int b[3][3]){for(int i=0;i<3;i++)for(int j=0;j<3;j++)b[j][2-i]=a[i][j];}\n原左上(0,0)应到右上(0,2)，可用这个角点检验方向。',['坐标映射','覆盖9项','顺时针方向']],
 ['实现int compressRuns(int a[],int n)，原地每个连续相等段只保留一项，返回新长度；不要求原数组有序。例如[2,2,1,2,2]变成前部[2,1,2]。','int compressRuns(int a[],int n){if(n==0)return 0;int k=1;for(int i=1;i<n;i++)if(a[i]!=a[k-1])a[k++]=a[i];return k;}\n这里只去连续重复，不把相隔的两个2合并。',['连续段语义','读写位置安全','空数组与非连续重复']],
 ['实现int encodeRuns(const int a[],int n,int values[],int lens[])，输出每个连续段的值与长度，输出容量n，返回段数；n≥0。','int encodeRuns(const int a[],int n,int values[],int lens[]){int k=0,i=0;while(i<n){int start=i,x=a[i];while(i<n&&a[i]==x)i++;values[k]=x;lens[k]=i-start;k++;}return k;}\n外层每轮处理一整段，内层在读a[i]前先检查边界。',['段起点和值','内层有界','值与长度并列输出','总O(n)']]
]);
export const waveTwoPractice=courses;
